#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "config/aom_config.h"
#include "av1/common/av1_loopfilter.h"

// declare the SIMD dispatch symbol via rtcd-like externs (they are macros normally)
extern void aom_lpf_horizontal_14_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_14(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_8_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_6_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_14_dual_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_8_dual_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_6_dual_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_4_dual_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*,const uint8_t*);
extern void aom_lpf_horizontal_4_sse2(uint8_t*,int,const uint8_t*,const uint8_t*,const uint8_t*);

typedef void (*LpfFunc)(uint8_t *s, int p, const uint8_t *blimit,
                        const uint8_t *limit, const uint8_t *thresh);

// exact copy of vulnerable filter_selectively_horiz
static void v_filter_selectively_horiz(uint8_t *s, int pitch, int plane,
                                     int subsampling, uint64_t mask_16x16,
                                     uint64_t mask_8x8, uint64_t mask_4x4,
                                     const loop_filter_info_n *lfi_n,
                                     const uint8_t *lfl) {
  uint64_t mask;
  int count;
  const int step = 1 << subsampling;
  const unsigned int two_block_mask = subsampling ? 5 : 3;

  for (mask = mask_16x16 | mask_8x8 | mask_4x4; mask; mask >>= step * count) {
    const loop_filter_thresh *lfi = lfi_n->lfthr + *lfl;
    const loop_filter_thresh *lfin = lfi_n->lfthr + *(lfl + step);
    (void)lfin;
    count = 1;
    if (mask & 1) {
      if (mask_16x16 & 1) {
        LpfFunc lpf_horizontal = plane ? aom_lpf_horizontal_6_sse2 : aom_lpf_horizontal_14_sse2;
        if ((mask_16x16 & two_block_mask) == two_block_mask) {
          if (plane) {
            aom_lpf_horizontal_6_dual_sse2(s, pitch, lfi->mblim, lfi->lim, lfi->hev_thr, lfin->mblim, lfin->lim, lfin->hev_thr);
          } else {
            aom_lpf_horizontal_14_dual_sse2(s, pitch, lfi->mblim, lfi->lim, lfi->hev_thr, lfin->mblim, lfin->lim, lfin->hev_thr);
          }
          count = 2;
        } else {
          lpf_horizontal(s, pitch, lfi->mblim, lfi->lim, lfi->hev_thr);
        }
      } else if (mask_8x8 & 1) {
        LpfFunc lpf_horizontal = plane ? aom_lpf_horizontal_6_sse2 : aom_lpf_horizontal_8_sse2;
        if ((mask_8x8 & two_block_mask) == two_block_mask) {
          if (plane) aom_lpf_horizontal_6_dual_sse2(s,pitch,lfi->mblim,lfi->lim,lfi->hev_thr,lfin->mblim,lfin->lim,lfin->hev_thr);
          else aom_lpf_horizontal_8_dual_sse2(s,pitch,lfi->mblim,lfi->lim,lfi->hev_thr,lfin->mblim,lfin->lim,lfin->hev_thr);
          count = 2;
        } else lpf_horizontal(s,pitch,lfi->mblim,lfi->lim,lfi->hev_thr);
      } else if (mask_4x4 & 1) {
        if ((mask_4x4 & two_block_mask) == two_block_mask) {
          aom_lpf_horizontal_4_dual_sse2(s,pitch,lfi->mblim,lfi->lim,lfi->hev_thr,lfin->mblim,lfin->lim,lfin->hev_thr);
          count = 2;
        } else aom_lpf_horizontal_4_sse2(s,pitch,lfi->mblim,lfi->lim,lfi->hev_thr);
      }
    }
    s += 4 * count;
    lfl += step * count;
    mask_16x16 >>= step * count;
    mask_8x8 >>= step * count;
    mask_4x4 >>= step * count;
  }
}

int main(){
  int N=2; // two blocks
  LoopFilterMask *lfm=(LoopFilterMask*)calloc(N,sizeof(LoopFilterMask));
  loop_filter_info_n *lfi_n=calloc(1,sizeof(loop_filter_info_n));
  // frame buffer: 64x64 + border, stride 128
  int stride=128; uint8_t *frame=calloc(1,stride*128);
  // set lfl levels all to 63 to maximize lfthr offset
  for(int i=0;i<N;i++) for(int r=0;r<16;r++)for(int c=0;c<16;c++){lfm[i].lfl_y_hor[r][c]=63;lfm[i].lfl_u_hor[r][c]=63;lfm[i].lfl_v_hor[r][c]=63;}
  uint8_t *s=frame+8*stride+8; // interior

  fprintf(stderr,"case1: LUMA row15 off15, bit15 only, first block\n");
  uint8_t *lfl=&lfm[0].lfl_y_hor[15][0];
  v_filter_selectively_horiz(s,stride,0,0,0x8000ULL,0,0,lfi_n,lfl);
  fprintf(stderr,"case2: same but LAST array element lfm[N-1]\n");
  lfl=&lfm[N-1].lfl_y_hor[15][0];
  v_filter_selectively_horiz(s,stride,0,0,0x8000ULL,0,0,lfi_n,lfl);
  fprintf(stderr,"case3: chroma V row15, bit14 (col15), lfl from lfl_v_hor[15][1]\n");
  lfl=&lfm[N-1].lfl_v_hor[15][1];
  v_filter_selectively_horiz(s,stride,2,1,0x4000ULL,0,0,lfi_n,lfl); // extracted rel bit14
  fprintf(stderr,"case4: LUMA full row15 all bits set\n");
  lfl=&lfm[N-1].lfl_y_hor[15][0];
  v_filter_selectively_horiz(s,stride,0,0,0xFFFFULL,0,0,lfi_n,lfl);
  fprintf(stderr,"all done\n");
  return 0;
}
EOF
